\looseness=-1 \textbf{Note on $\varepsilon$ comparisons.}\enspace The $\tau$-sweep uses $\varepsilon{=}0.2$ (the adaptive pipeline's norm bound). CRM always-on in Table~\ref{tab:main} uses a tighter $\varepsilon{=}0.05$ to limit overcorrection when applied unconditionally. The two settings are not directly comparable: CRM always-on ($\varepsilon{=}0.05$, 100\% trigger) achieves 85.5\% on Goal seed 42, exceeding $\tau{=}0.10$ ($\varepsilon{=}0.2$, 73.9\% trigger) at 81.0\%. This reflects the interaction between correction magnitude and trigger frequency: unconditional correction requires a gentler $\varepsilon$ to remain stable, while gated correction tolerates a larger $\varepsilon$ because it fires selectively.


\section{Uncertainty Proxy Comparison}
\label{sec:proxy_comparison}

\begin{table}[h]
\centering
\caption{Spearman $\rho$ between candidate uncertainty proxies and $K{=}10$ action variance (ground-truth uncertainty). Evaluated on LIBERO-Object (10 tasks $\times$ 10 rollouts, 27{,}626 steps). Only pairwise $L_2$ distance achieves meaningful correlation.}
\label{tab:proxy_comparison}
\small
\begin{tabular}{lcc}
\toprule
Proxy & Spearman $\rho$ & Extra VLA calls \\
\midrule
$K{=}2$ pairwise $L_2$ (ours) & $\mathbf{0.9979}$ & 1 \\
$K{=}1$ CRM correction magnitude & $0.152$ & 0 \\
$K{=}2$ CRM correction magnitude & $0.134$ & 1 \\
Flow velocity dispersion (FMVD) & $0.083$ & 0 \\
\bottomrule
\end{tabular}
\end{table}

\looseness=-1 Table~\ref{tab:proxy_comparison} compares four candidate uncertainty proxies against $K{=}10$ sample variance as ground truth. CRM correction magnitude (the $L_2$ norm of the CRM's predicted residual) is attractive because it requires no extra VLA forward passes, but correlates weakly with true uncertainty ($\rho \leq 0.15$): the CRM predicts similar-magnitude corrections regardless of whether the VLA is confident or uncertain. FMVD, which measures dispersion in the flow-matching velocity field, performs worse still ($\rho{=}0.083$). The $K{=}2$ pairwise $L_2$ distance achieves near-perfect correlation ($\rho{=}0.9979$) at the cost of one additional VLA forward pass, which is absorbed by batched inference (Section~\ref{sec:magnitude_results}).

